"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[6340],{57473:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"ArmorConfig","desc":"Single tuning surface for crafted player armor. Armor comes in two types that\\ndiffer only in what happens when their pool empties: a **Ballistic** kind\'s\\npool is durability and the set is destroyed at zero; an **Energy** kind\'s pool\\nis a reserve that can be recharged at the workbench and simply stops\\nprotecting while empty. Both drain by the damage the armor actually absorbed.\\n\\nEnergy kinds always reduce less than the ballistic kind of the same tier,\\ntrading raw mitigation for a refillable pool.\\n\\nKind id is the persisted unit (see `ArmorManager`), alongside the pool\\n*remaining*. Reduction, maximum pool, type and tier are always derived from\\nthis table, so retuning a kind retroactively updates every player holding it.\\nPer project convention, tune armor here, not in code.","source":{"line":19,"path":"src/ReplicatedStorage/SharedModules/Configs/ArmorConfig.luau"}}')}}]);